mapper.select:
SELECT si.*, sc.name AS category_name FROM supply_item si LEFT JOIN supply_category sc ON si.category_id = sc.id
AND (si.name LIKE CONCAT('%', #{keyword}, '%') OR si.code LIKE CONCAT('%', #{keyword}, '%') OR si.manufacturer LIKE CONCAT('%', #{keyword}, '%'))
AND si.category_id = #{categoryId}
AND si.status = #{status}
ORDER BY si.create_time DESC

mapper.update:
UPDATE supply_item
SET quantity = quantity + #{delta}
WHERE id = #{id}

UPDATE supply_item
SET quantity = quantity - #{delta}
WHERE id = #{id}
  AND quantity >= #{delta}
